#include "c_gradbench_linrouting_d.h"

/*
  Differentiation of rol_route_runtimestep in forward (tangent) mode:
   variations   of useful results: *flux *state
   with respect to varying inputs: *flux qstar1 theta x0 *state
   Plus diff mem management of: flux:in state:in
*/
int rol_route_runtimestep_d(double qstar1, double qstar1d, double timestep, 
        double gamma, double theta, double thetad, double x0, double x0d, 
        double *state, double *stated, double *flux, double *fluxd) {
    /* Quasaore coefficients
     * dx/dt = Q1* / ? - 1/? f(x)
     * f(x) = 1/? x    with ? dimless
     * hence dx/dt = Q1* / ? - ?/?  x
     *
     * x(t) = Q1* ? * ? / ? + (x0 - Q1* ? * ? / ? ) exp(- x / ]
)
     *
     * Output flux = Q1* - Q1 - Q2
     * F = Q1* - Q1* (1 - intx / ?)
     */
    double xbar = qstar1*timestep*theta/gamma;
    double xbard = timestep*(theta*qstar1d+qstar1*thetad)/gamma;
    double temp;
    double temp0;
    temp = 1.0/theta;
    temp0 = exp(-temp);
    double x1 = xbar + (x0-xbar)*temp0;
    double x1d = xbard + temp0*(x0d-xbard) + (x0-xbar)*exp(-temp)*temp*thetad/
    theta;
    *stated = x1d;
    *state = x1;
    *fluxd = qstar1d - gamma*(x1d-x0d)/timestep;
    *flux = qstar1 - gamma/timestep*(x1-x0);
    return 0;
}

/*
  Differentiation of c_gradbench_linrouting in forward (tangent) mode:
   variations   of useful results: *qout_ro_route
   with respect to varying inputs: *thetas_ro_route
   RW status of diff variables: thetas_ro_route:(loc) *thetas_ro_route:in
                qout_ro_route:(loc) *qout_ro_route:out
   Plus diff mem management of: states_ro_route:in thetas_ro_route:in
                qout_ro_route:in
*/
int c_gradbench_linrouting_d(int nval, int nreaches, double timestep, double *
        x0_ro_route, double *thetas_ro_route, double *thetas_ro_routed, double
        *qin, double *states_ro_route, double *states_ro_routed, double *
        qout_ro_route, double *qout_ro_routed) {
    int i, j, k;
    double qi;
    double qid;
    double xini;
    double xinid;
    double theta;
    double thetad;
    *states_ro_routed = 0.0;
    *qout_ro_routed = 0.0;
    /* Loop through reaches */
    for (i = 0; i < nreaches; ++i) {
        /* initialise reach model */
        xini = x0_ro_route[i];
        thetad = thetas_ro_routed[i];
        theta = thetas_ro_route[i];
        xinid = 0.0;
        /* Time series loop */
        for (j = 0; j < nval; ++j) {
            /* Get inflow */
            k = j*nreaches + i - 1;
            qid = (i == 0 ? 0.0 : qout_ro_routed[k]);
            qi = (i == 0 ? qin[j] : qout_ro_route[k]);
            /* Run model */
            k = j*nreaches + i;
            rol_route_runtimestep_d(qi, qid, timestep, 1., theta, thetad, xini
                                    , xinid, &(states_ro_route[k]), &(
                                    states_ro_routed[k]), &(qout_ro_route[k]),
                                    &(qout_ro_routed[k]));
            /* Set timestep for next iteration */
            xinid = states_ro_routed[k];
            xini = states_ro_route[k];
        }
    }
    return 0;
}
